CREATE TABLE public.student_institution_visibility (institution_id uuid NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id uuid NOT NULL, areas text[] NOT NULL DEFAULT '{}', topics text[] NOT NULL DEFAULT '{}', sections text[] NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(institution_id,student_id));
GRANT SELECT ON public.student_institution_visibility TO authenticated; GRANT ALL ON public.student_institution_visibility TO service_role;
ALTER TABLE public.student_institution_visibility ENABLE ROW LEVEL SECURITY;
CREATE POLICY visibility_read ON public.student_institution_visibility FOR SELECT TO authenticated USING (student_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR coalesce(public.institution_role_of(institution_id)='direccion',false));
CREATE TABLE public.student_visibility_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution_id uuid NOT NULL, student_id uuid NOT NULL, actor_id uuid NOT NULL, before_value jsonb, after_value jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.student_visibility_history TO authenticated; GRANT ALL ON public.student_visibility_history TO service_role;
ALTER TABLE public.student_visibility_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY visibility_history_read ON public.student_visibility_history FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR coalesce(public.institution_role_of(institution_id)='direccion',false));
CREATE FUNCTION public.set_student_visibility(_inst uuid,_student uuid,_areas text[],_topics text[],_sections text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldrow jsonb; newrow jsonb; BEGIN
IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR coalesce(public.institution_role_of(_inst)='direccion',false)) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.institution_members WHERE institution_id=_inst AND user_id=_student AND member_role='estudiante') THEN RAISE EXCEPTION 'Estudiante ajeno'; END IF;
IF _areas IS NULL OR _topics IS NULL OR _sections IS NULL OR cardinality(_areas)>100 OR cardinality(_topics)>1000 OR cardinality(_sections)>100 OR EXISTS(SELECT 1 FROM unnest(_areas||_topics||_sections) x WHERE x IS NULL OR length(btrim(x)) NOT BETWEEN 1 AND 150) THEN RAISE EXCEPTION 'Selección inválida'; END IF;
IF EXISTS(SELECT 1 FROM unnest(_sections) x WHERE NOT EXISTS(SELECT 1 FROM public.institution_sections s JOIN public.section_students ss ON ss.section_id=s.id WHERE s.institution_id=_inst AND s.name=x AND ss.student_id=_student)) THEN RAISE EXCEPTION 'Sección no asignada'; END IF;
SELECT to_jsonb(v) INTO oldrow FROM public.student_institution_visibility v WHERE institution_id=_inst AND student_id=_student FOR UPDATE;
INSERT INTO public.student_institution_visibility(institution_id,student_id,areas,topics,sections) VALUES(_inst,_student,_areas,_topics,_sections) ON CONFLICT(institution_id,student_id) DO UPDATE SET areas=excluded.areas,topics=excluded.topics,sections=excluded.sections,updated_at=now() RETURNING to_jsonb(student_institution_visibility) INTO newrow;
INSERT INTO public.student_visibility_history(institution_id,student_id,actor_id,before_value,after_value) VALUES(_inst,_student,auth.uid(),oldrow,newrow); END $$;
REVOKE ALL ON FUNCTION public.set_student_visibility(uuid,uuid,text[],text[],text[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_student_visibility(uuid,uuid,text[],text[],text[]) TO authenticated;
CREATE FUNCTION public.institution_topic_visible(_inst uuid,_subject text,_topic text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR coalesce(public.institution_role_of(_inst) IN ('direccion','subdireccion','docente','administrativo'),false) OR EXISTS(SELECT 1 FROM public.student_institution_visibility v JOIN public.institution_members m ON m.institution_id=v.institution_id AND m.user_id=v.student_id AND m.member_role='estudiante' WHERE v.institution_id=_inst AND v.student_id=auth.uid() AND (_subject=ANY(v.areas) OR _topic=ANY(v.topics))) $$;
REVOKE ALL ON FUNCTION public.institution_topic_visible(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.institution_topic_visible(uuid,text,text) TO authenticated;
CREATE FUNCTION public.student_visible_schedules(_inst uuid,_student uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.institution_members WHERE institution_id=_inst AND user_id=_student AND member_role='estudiante') OR NOT (auth.uid()=_student OR EXISTS(SELECT 1 FROM public.guardian_links WHERE institution_id=_inst AND student_id=_student AND guardian_id=auth.uid() AND consented_at IS NOT NULL)) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF;
RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',h.id,'title',h.title,'grid',(SELECT coalesce(jsonb_object_agg(g.key,g.value),'{}'::jsonb) FROM jsonb_each(h.result->'grid') g WHERE g.key=ANY(v.sections) AND EXISTS(SELECT 1 FROM public.institution_sections s JOIN public.section_students ss ON ss.section_id=s.id WHERE s.institution_id=_inst AND s.name=g.key AND ss.student_id=_student)))) FROM public.institution_schedules h JOIN public.student_institution_visibility v ON v.institution_id=h.institution_id AND v.student_id=_student WHERE h.institution_id=_inst),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.student_visible_schedules(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.student_visible_schedules(uuid,uuid) TO authenticated;